import type { ProjectInfo, SourceExtension } from "./types.js";

/** Opaque, persistent repository identity; generated by core, not by the browser. */
export type ProjectId = string;

export interface IndexingSettings {
  extensions: SourceExtension[];
  /** Glob patterns relative to the project root, using forward slashes. */
  exclude: string[];
  respectGitignore: boolean;
}

/** ProjectInfo remains the minimal metadata available before engine startup. */
export interface Project extends ProjectInfo {
  id: ProjectId;
  indexing: IndexingSettings;
}
